typedef float rational_t;

class vector4d
{
public:
  rational_t x, y, z, w;

  inline const rational_t& operator[](int i) const
  {
    return (&x)[i];
  }

  inline rational_t& operator[](int i)
  {
    return (&x)[i];
  }
};

class matrix4x4
{
public:
  typedef vector4d row;

  row x __attribute__((aligned(16)));
  row y;
  row z;
  row w;

  inline const row& operator[](int i) const
  {
    return (&x)[i];
  }

  inline row& operator[](int i)
  {
    return (&x)[i];
  }

  matrix4x4 transpose();
};

matrix4x4 matrix4x4::transpose()
{
  static matrix4x4 loc;

	for(int i = 0; i < 4; ++i)
  {
		for(int j = 0; j < 4; ++j)
    {
			loc[i][j] = (*this)[j][i];
		}
  }

	return loc;
}
